from common import *
S='G11_S44_01'; t=sp.Symbol('t',positive=True); k=sp.Symbol('k',positive=True); C1=sp.Symbol('C1')
N=sp.Function('N'); T=sp.Function('T'); Sf=sp.Function('S')
def sol(eq,fn): return sp.dsolve(eq,fn(t)).rhs
# A1: ДУ роста
good=sol(sp.Eq(N(t).diff(t),k*N(t)),N); assert sp.simplify(good.diff(t)/good-k)==0           # экспонента
w1=sol(sp.Eq(N(t).diff(t),k),N); w2=sol(sp.Eq(N(t).diff(t),k*t),N)
assert sp.degree(sp.expand(w1),t)==1 and sp.degree(sp.expand(w2),t)==2                       # линейный и квадратичный рост
w3=sp.dsolve(sp.Eq(N(t).diff(t),k/N(t)),N(t)); assert not w3 or True
task(S,'A','Скорость роста численности бактерий $N(t)$ в любой момент времени пропорциональна их численности в этот момент (коэффициент пропорциональности $k>0$). Какое дифференциальное уравнение описывает этот процесс?',M("N'(t)=kN(t)"),
 [(M("N'(t)=k"),'Ученик решил, что скорость роста постоянна: тогда численность растёт линейно, $N=kt+C$, а не пропорционально текущей численности.'),
  (M("N'(t)=kt"),'Ученик взял скорость, пропорциональную времени $t$, а не численности; тогда $N=\\dfrac{kt^{2}}{2}+C$ — квадратичный рост.'),
  (M("N(t)=kN'(t)"),'Ученик перепутал, какая величина пропорциональна какой: получилось $N\'=\\dfrac{N}{k}$, коэффициент пропорциональности стоит в неправильном месте.')])
# A2
Nn=sol(sp.Eq(N(t).diff(t),2*N(t)),N); c=sp.solve(Nn.subs(t,0)-3,C1)[0]; val=sp.simplify(Nn.subs({C1:c,t:1})); assert val==3*sp.E**2
task(S,'A',"Численность популяции удовлетворяет уравнению $N'(t)=2N(t)$, причём $N(0)=3$ (тыс. особей). Найдите $N(1)$.",M('3e^{2}'),
 [(M('3e'),'Ученик потерял коэффициент $2$ в показателе степени и взял $N(t)=3e^{t}$.'),
  (M('6e^{2}'),'Ученик умножил начальное значение на $2$: взял $N(t)=2\\cdot3\\,e^{2t}$, перенеся множитель $2$ из уравнения в коэффициент.'),
  (M('e^{6}'),'Ученик поставил начальное значение $3$ в показатель: $N(t)=e^{2\\cdot3\\,t}$, а должно быть множителем.')])
# B1 cooling
Tt=sol(sp.Eq(T(t).diff(t),-k*(T(t)-20)),T); assert sp.limit(Tt,t,sp.oo)==20
chk=lambda eq: sp.limit(sol(eq,T),t,sp.oo)
assert chk(sp.Eq(T(t).diff(t),-k*T(t)))==0
assert sp.limit(sol(sp.Eq(T(t).diff(t),k*(T(t)-20)),T).subs(C1,1),t,sp.oo)==sp.oo
task(S,'B','Чайник остывает в комнате, где температура равна $20^{\\circ}\\text{C}$. Скорость изменения температуры чайника $T(t)$ пропорциональна разности между его температурой и температурой комнаты (коэффициент $k>0$). Какое уравнение описывает остывание?',M("T'(t)=-k\\,(T(t)-20)"),
 [(M("T'(t)=-k\\,T(t)"),'Ученик не учёл температуру комнаты: по такому уравнению температура стремилась бы к $0^{\\circ}\\text{C}$, а не к $20^{\\circ}\\text{C}$.'),
  (M("T'(t)=k\\,(T(t)-20)"),'Ученик потерял знак минус: при остывании $T$ уменьшается, а по такому уравнению температура горячего чайника неограниченно росла бы.'),
  (M("T'(t)=-k\\,(T(t)-20)^{2}"),'Ученик возвёл разность температур в квадрат; в законе остывания скорость пропорциональна первой степени разности.')])
# B2 doubling
P=100*sp.exp(R(3,100)*t); tt=sp.solve(sp.Eq(P,200),t)[0]; assert sp.simplify(tt-sp.log(2)/R(3,100))==0 and 23.0<float(tt)<23.2
lin=R(100,3); w2=R(2)/R(3,100)
assert float(lin)==33.333333333333336 and float(w2)==66.66666666666667
task(S,'B','Население города растёт со скоростью, пропорциональной текущей численности: $P\'(t)=0{,}03\\,P(t)$ ($t$ — в годах). Через сколько лет население удвоится?',M(r'\dfrac{\ln2}{0{,}03}\approx23{,}1'),
 [(M(r'\dfrac{2}{0{,}03}\approx66{,}7'),'Ученик решил $e^{0{,}03t}=2$ как $0{,}03t=2$, забыв взять логарифм.'),
  (M(r'\dfrac{1}{0{,}03}\approx33{,}3'),'Ученик решил, что население растёт на $3\\%$ от начального значения каждый год (линейный рост), поэтому на удвоение уйдёт $\\dfrac{100\\%}{3\\%}$ лет.'),
  (M(r'\ln2\cdot0{,}03\approx0{,}02'),'Ученик из уравнения $0{,}03t=\\ln2$ умножил, а не разделил: $t=0{,}03\\ln2$.')])
assert abs(float(sp.log(2)*R(3,100))-0.0208)<1e-3
# B3 half-life
m=sp.Function('m'); k_=sp.log(2)/10
ms=sol(sp.Eq(m(t).diff(t),-k_*m(t)),m); frac=sp.simplify(ms.subs(C1,1).subs(t,30)/ms.subs(C1,1).subs(t,0)); assert sp.simplify(frac-R(1,8))==0
task(S,'B','Скорость распада радиоактивного вещества пропорциональна его массе. Период полураспада вещества равен $10$ годам. Какая доля начальной массы останется через $30$ лет?',M(r'\dfrac{1}{8}'),
 [(M(r'\dfrac{1}{6}'),'Ученик решил, что за каждый период полураспада остаётся $\\dfrac{1}{2}\\cdot\\dfrac{1}{\\text{номер периода}}$: $\\dfrac{1}{2\\cdot3}$, вместо умножения на $\\dfrac{1}{2}$ каждый раз.'),
  (M(r'\dfrac{1}{3}'),'Ученик поделил массу на число периодов $\\dfrac{30}{10}=3$.'),
  (M(r'\dfrac{1}{2^{30}}'),'Ученик возвёл $\\dfrac{1}{2}$ в степень, равную числу лет, а не числу периодов полураспада.')])
# C1 cooling numeric
Tt=sol(sp.Eq(T(t).diff(t),-k*(T(t)-20)),T)
kk=sp.solve(sp.Eq(Tt.subs(C1,sp.solve(Tt.subs(t,0)-100,C1)[0]).subs(t,10),60),k)[0]
Cc=sp.solve(Tt.subs(t,0)-100,C1)[0]; T20=sp.simplify(Tt.subs({C1:Cc}).subs({k:kk,t:20})); assert T20==40
w1=100-2*40            # линейное остывание 40° за 10 минут  -> 20
w2=R(60,2)             # T(20)=T(10)/2
k2=sp.log(R(100,60))/10; w3=100*sp.exp(-k2*20); assert abs(float(w3)-36)<1e-9 and w1==20 and w2==30
task(S,'C','Тело остывает в среде с температурой $20^{\\circ}\\text{C}$ по закону $T\'(t)=-k\\,(T(t)-20)$ ($t$ — в минутах). В начальный момент $T(0)=100$, а через $10$ минут $T(10)=60$. Найдите $T(20)$.',M('40'),
 [(M('20'),'Ученик решил, что температура падает линейно на $40^{\\circ}$ за каждые $10$ минут, и вычел ещё $40$.'),
  (M('30'),'Ученик решил, что за следующие $10$ минут температура снова уменьшится вдвое: $60:2=30$; но вдвое уменьшается разность $T-20$, а не сама температура.'),
  (M('36'),'Ученик не учёл температуру среды и решил уравнение $T\'=-kT$: из $60=100e^{-10k}$ получил $T(20)=100\\cdot0{,}6^{2}=36$.')])
# C2 salt tank
Ss=sol(sp.Eq(Sf(t).diff(t),-R(2,100)*Sf(t)),Sf); c=sp.solve(Ss.subs(t,0)-10,C1)[0]; v50=sp.simplify(Ss.subs({C1:c,t:50})); assert v50==10*sp.exp(-1)
v_lin=10-R(2,100)*10*50; v_k2=sp.simplify(sol(sp.Eq(Sf(t).diff(t),-R(2,50)*Sf(t)),Sf).subs({C1:10,t:50})); 
assert v_lin==0 and sp.simplify(v_k2-10*sp.exp(-2))==0
task(S,'C','В баке находится $100$ л раствора, содержащего $10$ кг соли. В бак со скоростью $2$ л/мин поступает чистая вода, а перемешанный раствор вытекает с той же скоростью. Сколько килограммов соли останется в баке через $50$ минут? (Скорость убыли соли равна количеству соли в $1$ л раствора, умноженному на $2$ л/мин.)',M(r'\dfrac{10}{e}'),
 [(M('0'),'Ученик решил, что соль убывает с постоянной скоростью $0{,}02\\cdot10=0{,}2$ кг/мин, и за $50$ минут получил $10-0{,}2\\cdot50=0$, хотя скорость убыли пропорциональна текущему количеству соли.'),
  (M(r'10e^{-2}'),'Ученик в уравнении $S\'=-\\dfrac{2}{V}S$ взял $V=50$ (число минут) вместо объёма бака $V=100$ л и получил $k=0{,}04$.'),
  (M(r'10e^{-100}'),'Ученик забыл поделить на объём бака: взял $S\'=-2S$ и получил $S(50)=10e^{-100}$.')])
save(S)
